<script>
  import ProLock from "$lib/pro/ProLock.svelte";
  import { entitled, loadPlan } from "$lib/pro/plan.svelte.js";
  import { ask } from "$lib/ui/confirm.svelte.js";
  import ChipInput from "$lib/ui/ChipInput.svelte";
  import ChoiceMulti from "$lib/ui/ChoiceMulti.svelte";
  import { rangeProblem } from "$lib/lists.js";
  import { live } from "$lib/live.js";
  // The developer console: API keys, webhooks with their delivery log (and replay), all in one place. `section` picks "keys" or "webhooks".
  import { onMount } from "svelte";
  import { api } from "$lib/api.js";
  import { when } from "$lib/docs.js";
  import { toast } from "$lib/ui/toast.js";
  import { t } from "$lib/i18n/index.svelte.js";
  import Rich from "$lib/i18n/Rich.svelte";
  import Sheet from "$lib/ui/Sheet.svelte";
  import SecretField from "$lib/ui/SecretField.svelte";
  import Dialog from "$lib/ui/Dialog.svelte"; import DataTable from "$lib/ui/DataTable.svelte"; import Segment from "$lib/ui/Segment.svelte"; import Kbd from "$lib/ui/Kbd.svelte"; import Icon from "$lib/ui/Icon.svelte"; import ApiCall from "$lib/ui/ApiCall.svelte";
  import StatusChip from "$lib/ui/StatusChip.svelte"; import RelativeTime from "$lib/ui/RelativeTime.svelte";
  let detail = $state(null), sel = $state(null);
  const HCOLS = $derived([{ key: "url", label: t("Endpoint") }, { key: "events", label: t("Events") }, { key: "status", label: t("Status") }, { key: "actions", label: "", align: "right" }]);
  async function openDetail(e) { detail = e; sel = null; open = e.id; const r = await api(`/api/developer/webhook-endpoints/${e.id}/deliveries`); logFailed = { ...logFailed, [e.id]: r.ok ? null : (r.error ?? t("The delivery log could not be loaded.")) }; log = { ...log, [e.id]: r.ok ? (r.json?.deliveries ?? []) : [] }; if (!r.ok) toast(r.error ?? t("The delivery log could not be loaded."), "bad"); }   // R13-D448: a failed read is not "No real events have been sent"
  const KCOLS = $derived([{ key: "name", label: t("Name") }, { key: "token", label: t("Token") }, { key: "permission", label: t("Permission") }, { key: "used", label: t("Last used") }, { key: "created", label: t("Created") }, { key: "actions", label: "", align: "right" }]);
  const permOf = (k) => { const sc = k.scopes ?? []; return (scopes.length ? sc.length >= scopes.length : sc.length >= 13) ? t("Full access") : sc.length && sc.every((x) => /:read$/.test(x)) ? t("Read only") : t("{n, plural, one {# permission} other {# permissions}}", { n: sc.length }); };
  let { section = "keys" } = $props();
  let keys = $state(null), scopes = $state([]), eps = $state(null), topics = $state({}), problem = $state(null), fresh = $state(null), open = $state(null), log = $state({}), logFailed = $state({}), epsFailed = $state(null), busy = $state(false), sheet = $state(null), replaying = $state(null);
  // R13-D104/D141: every event a Docustay action produces can be picked here, not only the seven document ones; these four come only from the platform paths (records archive, HTML-template publish and versioning) and are left out
  const WORKBENCH_ONLY = new Set(["documents.document.archived", "documents.template.published", "documents.template.versioned", "documents.template.updated", "documents.type.created", "documents.category.created", "documents.disclosure.accepted", "documents.disclosure.withdrawn"]);   // R13-D104 follow-up: no Docustay v1 screen or action produces these (R13-D230: downloaded and delegated do — download links and "Pass to someone else" — so they are offered; the server now sends only real ones)
  let kdraft = $state(false), kmaxd = $state(""), kmaxs = $state(""), pol = $state(null), polDraft = $state(false), polMaxD = $state(""), polMaxS = $state(""), kdays = $state(""), kallow = $state([]), edit = $state(null), editAllow = $state([]), kenv = $state("test"), kname = $state(""), kscopes = $state(["documents:read"]), url = $state(""), picked = $state(["documents.document.executed"]), pickedMore = $state([]);
  async function load() {
    loadPlan();
    const [k, s, e, tp] = await Promise.all([api("/api/developer/api-keys"), api("/api/developer/scopes"), api("/api/developer/webhook-endpoints"), api("/api/developer/webhook-topics")]);
    if (!k.ok) { problem = k.error ?? t("Developer settings could not be loaded."); return; }
    epsFailed = e.ok ? null : (e.error ?? t("Webhook endpoints could not be loaded."));   // R13-D448: a failed read is not "No endpoints yet."
    keys = k.json.keys; scopes = (s.json?.scopes ?? []).filter((x) => /^(documents|templates|webhooks|account|embedded|plays|drafts):/.test(x) || x === "people:read"); eps = e.json?.endpoints ?? []; topics = tp.json?.topics ?? {};
  }
  // D-019: "last used" changes from outside this page (a script calling the API), so the list is read again whenever the tab is looked at again
  onMount(() => { load(); const stopLive = live(["keys", "webhooks"], load); const again = () => { if (document.visibilityState === "visible") load(); }; document.addEventListener("visibilitychange", again); window.addEventListener("focus", again); return () => { stopLive?.(); document.removeEventListener("visibilitychange", again); window.removeEventListener("focus", again); }; });
  const toggle = (arr, v) => (arr.includes(v) ? arr.filter((x) => x !== v) : [...arr, v]);
  // a daily limit is picked from a short list; a number saved earlier that is not on it stays on the list
  const limitList = (cur) => { const base = [10, 25, 50, 100, 250, 500, 1000, 5000]; const c = Number(cur); return c && !base.includes(c) ? [...base, c].sort((a, b) => a - b) : base; };
  async function mint() { busy = true; const r = await api("/api/developer/api-keys", { method: "POST", body: { name: kname.trim(), scopes: kscopes, environment: kenv, ...(kdays ? { expiresInDays: Number(kdays) } : {}), ...(kallow.length ? { ipAllowlist: kallow } : {}), ...(kdraft ? { draftOnly: true } : {}), ...(kmaxd ? { maxDraftsPerDay: Number(kmaxd) } : {}), ...(kmaxs ? { maxSendsPerDay: Number(kmaxs) } : {}) } }); busy = false; if (r.ok) { fresh = r.json?.key; kname = ""; kdays = ""; kallow = []; kdraft = false; kmaxd = ""; kmaxs = ""; sheet = null; await load(); } else toast(r.error ?? t("The key could not be made."), "bad"); }
  // R13-D087: rotate = a replacement with the same permissions, shown once; the old key keeps working until it is revoked, so nothing breaks mid-switch. Revoked keys are hidden unless asked for. The list can be taken as a CSV.
  let showRevoked = $state(false);
  const shownKeys = $derived(showRevoked ? keys : keys.filter((k) => !k.revoked_at));
  async function rotateKey(k) { if (!await ask(t("Make a replacement for “{name}” with the same permissions? The old key keeps working until you revoke it.", { name: k.name }))) return; const p = k.policy ?? {}; const r = await api("/api/developer/api-keys", { method: "POST", body: { name: `${k.name} (new)`, scopes: k.scopes, environment: k.environment, ...(k.ip_allowlist?.length ? { ipAllowlist: k.ip_allowlist } : {}), ...(p.draftOnly ? { draftOnly: true } : {}), ...(p.maxDraftsPerDay ? { maxDraftsPerDay: p.maxDraftsPerDay } : {}), ...(p.maxSendsPerDay ? { maxSendsPerDay: p.maxSendsPerDay } : {}) } }); if (r.ok) { fresh = r.json?.key; toast(t("New key made. Switch over, then revoke the old one."), "ok"); await load(); } else toast(r.error ?? t("The key could not be made."), "bad"); }
  const kcell = (v) => { const x = String(v ?? ""); return /[",\n]/.test(x) ? `"${x.replace(/"/g, '""')}"` : x; };
  function downloadKeys() { const csv = ["name,environment,permissions,created,last_used,expires,revoked", ...keys.map((k) => [k.name, k.environment, (k.scopes ?? []).join(" "), k.created_at, k.last_used_at, k.expires_at, k.revoked_at].map(kcell).join(","))].join("\n"); const a = document.createElement("a"); a.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" })); a.download = "api-keys.csv"; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 2000); }
  async function savePolicy() { busy = true; const r = await api(`/api/developer/api-keys/${pol.id}/policy`, { method: "POST", body: { draftOnly: polDraft, maxDraftsPerDay: polMaxD ? Number(polMaxD) : null, maxSendsPerDay: polMaxS ? Number(polMaxS) : null } }); busy = false; if (r.ok) { pol = null; await load(); } else toast(r.error ?? t("That did not save."), "bad"); }
  async function saveAllow() { busy = true; const r = await api(`/api/developer/api-keys/${edit.id}/allowlist`, { method: "POST", body: { ipAllowlist: editAllow } }); busy = false; if (r.ok) { edit = null; await load(); } else toast(r.error ?? t("The addresses could not be saved."), "bad"); }
  let testing = $state(null), tested = $state({});
  // D-021: the receiver's reply, as a short plain line (no markup, one line, at most 80 characters) — never a page of raw HTML in a notice
  // A receiver's reply is shown only when it is a short plain sentence: a whole web page (its styles and scripts included) says nothing useful next to the status, so it is left out.
  const brief = (x) => { const raw = String(x ?? ""); if (/<\s*(!doctype|html|head|body|style|script)/i.test(raw)) return ""; const s = raw.replace(/<[^>]*>/g, " ").replace(/\s+/g, " ").trim(); return /[{};]/.test(s) ? "" : s.slice(0, 80); };
  async function sendTest(e) { testing = e.id; const r = await api(`/api/developer/webhook-endpoints/${e.id}/test`, { method: "POST", body: {} }); testing = null; tested = { ...tested, [e.id]: r.ok ? r.json : { outcome: "failed", error: r.error ?? t("The test could not be sent.") } }; }
  // D-022: a new secret starts clean — the earlier test's failure no longer applies
  async function rotate(e) { if (!await ask(t("Make a new signing secret for this address? The old one keeps working beside it for 24 hours, so you can switch without missing anything."))) return; const r = await api(`/api/developer/webhook-endpoints/${e.id}/rotate`, { method: "POST", body: { windowHours: 24 } }); if (r.ok) { fresh = r.json?.secret; tested = { ...tested, [e.id]: undefined }; await load(); } else toast(r.error ?? t("The secret could not be changed."), "bad"); }
  async function revoke(k) { if (!await ask(t("Revoke “{name}”? Anything using it stops working.", { name: k.name }))) return; const r = await api(`/api/developer/api-keys/${k.id}/revoke`, { method: "POST", body: {} }); toast(r.ok ? t("Revoked.") : (r.error ?? t("That did not work.")), r.ok ? "ok" : "bad"); await load(); }
  // R13-D476: a new endpoint starts from the defaults, not from the events chosen for the one before it.
  let editing = $state(null);
  const FIRST_GROUP = /\.(sent|opened|signed|executed|declined|voided|expired)$/;
  function resetHook() { editing = null; url = ""; picked = ["documents.document.executed"]; pickedMore = []; }
  // R13-D107: change the events of an endpoint, pause or resume it, or remove it
  function editHook(e) { const ev = e.event_types ?? e.eventTypes ?? []; editing = e.id; url = e.url; picked = ev.filter((x) => FIRST_GROUP.test(x)); pickedMore = ev.filter((x) => !FIRST_GROUP.test(x)); sheet = "hook"; }
  async function pauseHook(e) { const pausing = !e.status || e.status === "active"; const r = await api(`/api/developer/webhook-endpoints/${e.id}`, { method: "PATCH", body: { paused: pausing } }); if (r.ok) { toast(pausing ? t("Paused. Nothing is sent to this address until you resume it.") : t("Resumed."), "ok"); await load(); } else toast(r.error ?? t("That could not be changed."), "bad"); }
  async function removeHook(e) { if (!await ask(t("Remove this address? Nothing more is sent to it. Its past deliveries stay in the record."))) return; const r = await api(`/api/developer/webhook-endpoints/${e.id}`, { method: "DELETE" }); if (r.ok) { toast(t("Removed."), "ok"); await load(); } else toast(r.error ?? t("That could not be removed."), "bad"); }
  async function addHook() { if (editing) { busy = true; const r = await api(`/api/developer/webhook-endpoints/${editing}`, { method: "PATCH", body: { event_types: [...picked, ...pickedMore] } }); busy = false; if (r.ok) { toast(t("Events saved."), "ok"); resetHook(); sheet = null; await load(); } else toast(r.error ?? t("The events could not be saved."), "bad"); return; } busy = true; let name = "endpoint"; try { name = new URL(url.trim()).hostname; } catch { /* the server refuses a bad address */ } const r = await api("/api/developer/webhook-endpoints", { method: "POST", body: { url: url.trim(), name, event_types: [...picked, ...pickedMore] } }); busy = false; if (r.ok) { fresh = r.json?.secret ?? null; resetHook(); sheet = null; await load(); } else toast(r.error ?? t("The endpoint could not be added."), "bad"); }
  async function showLog(e) { if (open === e.id) { open = null; return; } open = e.id; const r = await api(`/api/developer/webhook-endpoints/${e.id}/deliveries`); logFailed = { ...logFailed, [e.id]: r.ok ? null : (r.error ?? t("The delivery log could not be loaded.")) }; log = { ...log, [e.id]: r.ok ? (r.json?.deliveries ?? []) : [] }; if (!r.ok) toast(r.error ?? t("The delivery log could not be loaded."), "bad"); }
  async function replay(e, d) {
    if (replaying) return;   // one at a time: a second click while the first is in flight would send the event twice
    replaying = d.id;
    const r = await api("/api/developer/webhook-deliveries/replay", { method: "POST", body: { deliveryId: d.id } });
    replaying = null;
    const out = r.json?.outcome, code = r.json?.status ? ` (${r.json.status})` : "";
    if (!r.ok) toast(r.error ?? t("That could not be replayed."), "bad");
    else if (out === "refused") toast(t("Not sent: {reason}.", { reason: r.json?.reason ?? t("it could not be replayed") }), "bad");
    else if (out === "delivered") toast(t("Sent again — your address accepted it{code}.", { code }), "ok");
    else toast(t("Sent again, but your address did not accept it{code}. It will be retried by the usual schedule.", { code }), "bad");
    const l = await api(`/api/developer/webhook-endpoints/${e.id}/deliveries`); if (l.ok) log = { ...log, [e.id]: l.json?.deliveries ?? [] };
  }
  const tone = (d) => (d.status === "succeeded" || d.status === "delivered" || (d.response_status >= 200 && d.response_status < 300) ? "ok" : d.dead_at ? "bad" : d.next_retry_at ? "warn" : "mute");
</script>
{#if problem}<p class="notice bad" role="alert" data-testid="dev-failed">{problem} <button class="btn quiet" onclick={() => { problem = null; load(); }}>{t("Try again")}</button></p>{:else if !keys}<p class="text-mute">{t("Loading…")}</p>{:else}
<div class=" space-y-6">
  {#if fresh}<div class="notice warn" role="status"><p class="font-medium">{t("Copy this now — it is not shown again.")}</p><div class="mt-2"><SecretField value={String(fresh)} /></div><button class="btn mt-2 !min-h-9" onclick={() => (fresh = null)}>{t("I have copied it")}</button></div>{/if}
  {#if section === "keys"}
  <section><h2 class="text-xl font-semibold">{t("API keys")}</h2><p class="mb-3 mt-1 text-sm text-mute"><Rich text={t("A key lets your own software use Docustay. Give each one only what it needs. Every plan can make as many keys as it needs. The full API is described at <spec>/api/v1/openapi.json</spec> and in the <dev>developer docs</dev>.")} parts={{ spec: { href: "/api/v1/openapi.json", class: "text-brand underline" }, dev: { href: "/developers", class: "text-brand underline" } }} /></p>
    {#if keys.length}<div class="mb-2 flex items-center justify-between gap-3"><label class="flex items-center gap-2 text-sm text-mute"><input type="checkbox" bind:checked={showRevoked} data-testid="keys-show-revoked" />{t("Show revoked keys")}</label><button class="btn" onclick={downloadKeys} data-testid="keys-download">{t("Download the list (CSV)")}</button></div><DataTable columns={KCOLS} rows={shownKeys} rowKey={(k) => k.id} testid="key-table">{#snippet cell(k, c)}
      {#if c.key === "name"}<span class="font-medium">{k.name}</span>{#if k.revoked_at}<span class="chip mute ml-2">{t("revoked")}</span>{/if}
      {:else if c.key === "token"}<code class="rounded-md border border-line bg-tint px-1.5 py-0.5 font-mono text-[12px]">{k.prefix ?? `dsk_${k.environment ?? "test"}_`}••••{k.last_four ?? k.lastFour ?? ""}</code>
      {:else if c.key === "permission"}<span class="flex flex-wrap items-center gap-1"><span class="chip {(k.environment ?? k.env) === 'live' ? 'ok' : 'warn'}">{(k.environment ?? k.env) === "live" ? t("Live") : t("Test")}</span><span class="chip {permOf(k) === t('Full access') ? 'info' : 'mute'}" title={(k.scopes ?? []).join(", ")}>{permOf(k)}</span>{#if k.policy?.draftOnly}<span class="chip mute" data-testid="key-draftonly-chip">{t("draft only")}</span>{/if}{#if k.policy?.maxDraftsPerDay || k.policy?.maxSendsPerDay}<span class="chip mute" data-testid="key-limits-chip">{t("{d} drafts · {s} sends a day", { d: k.policy.maxDraftsPerDay ?? "∞", s: k.policy.maxSendsPerDay ?? "∞" })}</span>{/if}{#if (k.ip_allowlist ?? []).length}<span class="chip mute" title={(k.ip_allowlist ?? []).join(", ")} data-testid="key-allow">{t("{n, plural, one {# address} other {# addresses}} only", { n: k.ip_allowlist.length })}</span>{/if}{#if k.expires_at}<span class="text-xs {new Date(k.expires_at) < new Date(Date.now() + 14 * 864e5) ? 'text-warn' : 'text-mute'}" data-testid="key-expiry">{new Date(k.expires_at) < new Date() ? t("expired {date}", { date: when(k.expires_at) }) : t("expires {date}", { date: when(k.expires_at) })}</span>{/if}</span>
      {:else if c.key === "used"}<span class="text-mute">{(k.last_used_at ?? k.lastUsedAt) ? t("used {date}", { date: when(k.last_used_at ?? k.lastUsedAt) }) : t("never used")}{k.last_used_ip ? ` · ${k.last_used_ip}` : ""}</span>
      {:else if c.key === "created"}<span class="text-mute">{k.created_at ?? k.createdAt ? when(k.created_at ?? k.createdAt) : "—"}</span>
      {:else}{#if !k.revoked_at}<span class="flex flex-wrap justify-end gap-1"><button class="btn !min-h-8 !px-2.5" onclick={() => { edit = k; editAllow = [...(k.ip_allowlist ?? [])]; }} data-testid="key-addresses">{t("Addresses")}</button><button class="btn !min-h-8 !px-2.5" onclick={() => rotateKey(k)} data-testid="key-rotate">{t("Rotate")}</button><button class="btn quiet !min-h-8 !px-2.5" onclick={() => { pol = k; polDraft = k.policy?.draftOnly === true; polMaxD = k.policy?.maxDraftsPerDay ?? ""; polMaxS = k.policy?.maxSendsPerDay ?? ""; }} data-testid="key-policy">{t("Limits")}</button><button class="btn danger !min-h-8 !px-2.5" onclick={() => revoke(k)}>{t("Revoke")}</button></span>{/if}{/if}
    {/snippet}</DataTable>{:else}<p class="text-sm text-mute">{t("No keys yet.")}</p>{/if}
    <div class="mt-3"><button class="btn primary" onclick={() => (sheet = "key")} data-testid="new-key">{t("New key")}</button></div>
    <Dialog open={sheet === "key"} title={t("Add API key")} onclose={() => (sheet = null)} testid="key-dialog">
      <form id="keyform" class="space-y-4" onsubmit={(e) => { e.preventDefault(); mint(); }} onkeydown={(e) => { if ((e.metaKey || e.ctrlKey) && e.key === "Enter") { e.preventDefault(); mint(); } }}><label class="label" for="kname">{t("Name")}</label><input id="kname" data-autofocus class="field" placeholder={t("What it is for (for example, my website)")} bind:value={kname} />
      <div><span class="label">{t("Key type")}</span><Segment label={t("Key type")} bind:value={kenv} options={[{ value: "test", label: t("Test") }, { value: "live", label: t("Live") }]} testid="key-env" /><p class="mt-1 text-xs text-mute">{kenv === "test" ? t("Test keys never email anyone but you.") : t("Live: real documents, emailed to the people you send to")}</p></div>
      <fieldset><legend class="label">{t("Allowed to")}</legend><div class="flex flex-wrap gap-x-4 gap-y-2 text-sm">{#each scopes as s}{#if /^(plays|drafts):/.test(s) && entitled("plays_api") === false}<ProLock item="plays_api" tip={t("The Plays and drafts API is part of Pro. The documents API works on every plan.")}>{#snippet children(locked)}<label class="flex items-center gap-2"><input type="checkbox" class="h-4 w-4 accent-[var(--brand)]" disabled={locked} checked={false} />{s}</label>{/snippet}</ProLock>{:else}<label class="flex items-center gap-2"><input type="checkbox" class="h-4 w-4 accent-[var(--brand)]" checked={kscopes.includes(s)} onchange={() => (kscopes = toggle(kscopes, s))} />{s}</label>{/if}{/each}</div></fieldset>
      <label class="label" for="kdays">{t("Expires")}</label><select id="kdays" class="field" bind:value={kdays} data-testid="key-days"><option value="">{t("Never")}</option><option value="30">{t("In 30 days")}</option><option value="90">{t("In 90 days")}</option><option value="365">{t("In a year")}</option></select>
      <label class="label" for="kallow">{t("Only from these addresses (optional)")}</label><ChipInput id="kallow" bind:value={kallow} max={20} placeholder="203.0.113.7 or 10.0.0.0/24" validate={rangeProblem} testid="key-allow-input" count={(n) => t("{n, plural, one {# address} other {# addresses}}", { n })} /><p class="text-xs text-mute">{t("Type or paste addresses. Leave empty to allow any address. Two keys can work at the same time, so you can change over to a new one before you revoke the old one.")}</p>
      <label class="flex items-center gap-2 text-sm"><input type="checkbox" bind:checked={kdraft} data-testid="key-draftonly" /> <span>{t("Draft only: it can make and edit drafts, but a person approves every send")}</span></label>
      <div class="grid grid-cols-2 gap-3"><label class="grid gap-1 text-sm"><span>{t("Drafts a day (optional)")}</span><select class="field" bind:value={kmaxd} data-testid="key-maxdrafts"><option value="">{t("No limit")}</option>{#each limitList(kmaxd) as n}<option value={String(n)}>{n}</option>{/each}</select></label><label class="grid gap-1 text-sm"><span>{t("Sends a day (optional)")}</span><select class="field" bind:value={kmaxs} data-testid="key-maxsends"><option value="">{t("No limit")}</option>{#each limitList(kmaxs) as n}<option value={String(n)}>{n}</option>{/each}</select></label></div>
      </form>
      {#snippet footer()}<button class="btn" type="button" onclick={() => (sheet = null)}>{t("Cancel")} <Kbd>Esc</Kbd></button><button class="btn primary" form="keyform" type="submit" disabled={busy || !kname.trim() || !kscopes.length || kallow.some((a) => rangeProblem(a))}>{t("Add")} <Kbd mod>↵</Kbd></button>{/snippet}
    </Dialog>
    
    <Sheet open={pol !== null} title={t("Limits for “{name}”", { name: pol?.name ?? "" })} onclose={() => (pol = null)}>
      <form class="space-y-4" onsubmit={(e) => { e.preventDefault(); savePolicy(); }}>
        <label class="flex items-center gap-2 text-sm"><input type="checkbox" bind:checked={polDraft} data-testid="pol-draftonly" /> <span>{t("Draft only: it can make and edit drafts, but a person approves every send")}</span></label>
        <label class="grid gap-1 text-sm"><span>{t("Drafts a day")}</span><select class="field" bind:value={polMaxD} data-testid="pol-maxdrafts"><option value="">{t("No limit")}</option>{#each limitList(polMaxD) as n}<option value={String(n)}>{n}</option>{/each}</select></label>
        <label class="grid gap-1 text-sm"><span>{t("Sends a day")}</span><select class="field" bind:value={polMaxS} data-testid="pol-maxsends"><option value="">{t("No limit")}</option>{#each limitList(polMaxS) as n}<option value={String(n)}>{n}</option>{/each}</select></label>
        <p class="text-xs text-mute">{t("Empty means no limit. The day is the UTC day. A call over the limit is refused with 429 and shows in the API log.")}</p>
        <button class="btn primary" disabled={busy} data-testid="pol-save">{t("Save")}</button>
      </form>
    </Sheet>
    <Sheet open={edit !== null} title={t("Addresses for “{name}”", { name: edit?.name ?? "" })} onclose={() => (edit = null)}>
      <form class="space-y-4" onsubmit={(e) => { e.preventDefault(); saveAllow(); }}><label class="label" for="eallow">{t("Only from these addresses")}</label><ChipInput id="eallow" bind:value={editAllow} max={20} placeholder="203.0.113.7 or 10.0.0.0/24" validate={rangeProblem} testid="key-allow-edit" count={(n) => t("{n, plural, one {# address} other {# addresses}}", { n })} /><p class="text-xs text-mute">{t("An address or a range, such as 203.0.113.7 or 10.0.0.0/24. Empty means any address. A call from anywhere else is refused, and the refusal appears in the API log.")}</p><button class="btn primary" disabled={busy || editAllow.some((a) => rangeProblem(a))} data-testid="key-allow-save">{t("Save")}</button></form>
    </Sheet></section>
  {:else}
  {#if detail}
  {@const ev = detail}{@const rows = log[ev.id] ?? []}{@const cur = rows.find((d) => d.id === sel) ?? rows[0]}
  <section data-testid="hook-detail">
    <button class="text-sm text-mute no-underline hover:text-ink" onclick={() => { detail = null; sel = null; open = null; }}>{t("← Webhooks")}</button>
    <header class="mb-6 mt-3 flex flex-wrap items-center gap-4"><span class="grid h-[52px] w-[52px] place-items-center rounded-[14px] border border-[var(--accent-line)] bg-[var(--accent-soft)] text-[var(--accent)]"><Icon name="webhook" size={22} /></span><h2 class="min-w-0 flex-1 break-all font-mono text-[20px] font-medium">{ev.url}</h2>
      <div class="flex gap-2"><button class="btn" onclick={() => sendTest(ev)} disabled={testing === ev.id} data-testid="hook-test">{testing === ev.id ? t("Sending…") : t("Send a test event")}</button><button class="btn" onclick={() => rotate(ev)} data-testid="hook-rotate">{t("Rotate secret")}</button></div></header>
    {#if tested[ev.id]}<p class="mb-3 text-sm {tested[ev.id].outcome === 'delivered' ? 'text-ok' : 'text-bad'}" role="status" data-testid="hook-test-result">{tested[ev.id].outcome === "delivered" ? t("Your address answered {status} in {ms} ms.", { status: tested[ev.id].status, ms: tested[ev.id].durationMs }) : t("Your address did not accept it: {why}", { why: tested[ev.id].error ?? tested[ev.id].outcome })}{brief(tested[ev.id].responseExcerpt) ? ` — ${brief(tested[ev.id].responseExcerpt)}` : ""}</p>{/if}
    <dl class="grid gap-x-8 gap-y-4 rounded-xl border border-line bg-card p-5 sm:grid-cols-4"><div><dt class="font-mono text-[.7rem] uppercase tracking-wider text-faint">{t("Listening for")}</dt><dd class="mt-1 flex flex-wrap gap-1">{#each (ev.event_types ?? ev.eventTypes ?? []) as x}<code class="rounded-md border border-line bg-tint px-1.5 py-0.5 text-[11.5px]">{x.replace("documents.document.", "")}</code>{/each}</dd></div><div><dt class="font-mono text-[.7rem] uppercase tracking-wider text-faint">{t("Status")}</dt><dd class="mt-1"><StatusChip tone={!ev.status || ev.status === "active" ? "ok" : "warn"}>{!ev.status || ev.status === "active" ? t("Enabled") : ev.status}</StatusChip></dd></div><div><dt class="font-mono text-[.7rem] uppercase tracking-wider text-faint">{t("Created")}</dt><dd class="mt-1 text-sm">{ev.created_at ? when(ev.created_at) : "—"}</dd></div><div><dt class="font-mono text-[.7rem] uppercase tracking-wider text-faint">{t("Signing secret")}</dt><dd class="mt-1 font-mono text-sm">whsec_••••••••</dd></div></dl>
    <div class="mt-6 grid gap-6 lg:grid-cols-[5fr_7fr]">
      <div><h3 class="mb-2 font-mono text-[11px] uppercase tracking-wider text-faint">{t("Events")}</h3>{#if logFailed[ev.id]}<p class="text-sm" role="alert" data-testid="hook-events-failed">{logFailed[ev.id]} <button class="btn quiet" onclick={() => openDetail(ev)}>{t("Try again")}</button></p>{:else if rows.length === 0}<p class="text-sm text-mute">{tested[ev.id] ? t("No real events have been sent to this address yet. Test sends are not counted and are not listed here; the result of your last test is shown above.") : t("Nothing sent to this address yet.")}</p>{:else}<ul class="grid gap-1 rounded-xl border border-line bg-card p-1" data-testid="hook-events-list">{#each rows as d (d.id)}<li><button class="flex w-full items-center gap-3 rounded-lg px-3 py-2 text-left hover:bg-tint {cur?.id === d.id ? 'bg-tint' : ''}" onclick={() => (sel = d.id)}><span class="min-w-0 flex-1"><span class="block truncate font-mono text-[12.5px]">{d.topic.replace("documents.document.", "documents.")}</span><span class="block text-[12px] text-mute"><RelativeTime value={d.attempted_at} /></span></span><StatusChip tone={tone(d)} spin={d.next_retry_at && !d.dead_at}>{tone(d) === "ok" ? t("Delivered") : d.next_retry_at ? t("Attempting") : (d.response_status ?? d.status)}</StatusChip></button></li>{/each}</ul>{/if}</div>
      <div>{#if cur}<div class="rounded-xl border border-line bg-card p-5" data-testid="hook-event"><div class="flex items-center justify-between gap-3"><h3 class="font-mono text-[17px] font-medium">{cur.topic}</h3><button class="btn" onclick={() => replay(ev, cur)} disabled={replaying !== null} data-testid="replay">{replaying === cur.id ? t("Sending…") : t("Replay")}</button></div>
        <dl class="mt-4 grid grid-cols-2 gap-4 text-sm sm:grid-cols-4"><div><dt class="font-mono text-[.7rem] uppercase tracking-wider text-faint">ID</dt><dd class="mt-1 truncate font-mono text-[12px]">{cur.event_id}</dd></div><div><dt class="font-mono text-[.7rem] uppercase tracking-wider text-faint">{t("Timestamp")}</dt><dd class="mt-1 text-[13px]">{when(cur.attempted_at)}</dd></div><div><dt class="font-mono text-[.7rem] uppercase tracking-wider text-faint">{t("HTTP status")}</dt><dd class="mt-1">{cur.response_status ?? "—"}</dd></div><div><dt class="font-mono text-[.7rem] uppercase tracking-wider text-faint">{t("Attempts")}</dt><dd class="mt-1">{cur.attempt}</dd></div></dl>
        <h4 class="mb-1 mt-5 font-mono text-[11px] uppercase tracking-wider text-faint">{t("Response")}</h4><pre tabindex="0" class="overflow-x-auto rounded-lg border border-line bg-[var(--code,var(--tint))] p-3 font-mono text-[12.5px]">{cur.error ?? (cur.response_status ? `HTTP ${cur.response_status}` : t("No answer yet."))}</pre>
        <h4 class="mb-1 mt-4 font-mono text-[11px] uppercase tracking-wider text-faint">{t("Message payload")}</h4><pre tabindex="0" class="overflow-x-auto rounded-lg border border-line bg-[var(--code,var(--tint))] p-3 font-mono text-[12.5px]">{JSON.stringify({ id: cur.event_id, type: cur.topic, data: cur.payload ?? {} }, null, 2)}</pre></div>{/if}</div>
    </div></section>
  {:else}
  <section><h2 class="text-xl font-semibold">{t("Webhooks")}</h2><p class="mb-3 mt-1 text-sm text-mute">{t("We call your address when something happens, signed so you can check it is us. Open an endpoint to see what was sent and to send any of it again.")}</p>
    {#if epsFailed}<p class="text-sm" role="alert" data-testid="hook-endpoints-failed">{epsFailed} <button class="btn quiet" onclick={load}>{t("Try again")}</button></p>{:else if eps.length}<DataTable columns={HCOLS} rows={eps} rowKey={(e) => e.id} testid="hook-table">{#snippet cell(e, c)}
      {#if c.key === "url"}<span class="break-all font-mono text-[12.5px]">{e.url}</span>
      {:else if c.key === "events"}<span class="text-mute">{t("{n, plural, one {# event} other {# events}}", { n: (e.event_types ?? e.eventTypes ?? []).length })}</span>
      {:else if c.key === "status"}<StatusChip tone={!e.status || e.status === "active" ? "ok" : "warn"}>{!e.status || e.status === "active" ? t("Enabled") : e.status === "paused" ? t("Paused") : e.status}</StatusChip>
      {:else}<span class="flex justify-end gap-1"><button class="btn !min-h-8 !px-2.5" onclick={() => sendTest(e)} disabled={testing === e.id} data-testid="hook-test">{testing === e.id ? t("Sending…") : t("Send a test event")}</button><button class="btn !min-h-8 !px-2.5" onclick={() => rotate(e)} data-testid="hook-rotate">{t("Rotate secret")}</button><button class="btn !min-h-8 !px-2.5" onclick={() => openDetail(e)} data-testid="hook-log">{t("Delivery log")}</button><button class="btn !min-h-8 !px-2.5" onclick={() => editHook(e)} data-testid="hook-edit">{t("Change events")}</button><button class="btn !min-h-8 !px-2.5" onclick={() => pauseHook(e)} data-testid="hook-pause">{!e.status || e.status === "active" ? t("Pause") : t("Resume")}</button><button class="btn !min-h-8 !px-2.5" onclick={() => removeHook(e)} data-testid="hook-remove">{t("Remove")}</button></span>{/if}
    {/snippet}</DataTable>{#each eps as e (e.id)}{#if tested[e.id]}<p class="mt-2 text-xs {tested[e.id].outcome === 'delivered' ? 'text-ok' : 'text-bad'}" role="status" data-testid="hook-test-result">{tested[e.id].outcome === "delivered" ? t("Your address answered {status} in {ms} ms.", { status: tested[e.id].status, ms: tested[e.id].durationMs }) : t("Your address did not accept it: {why}", { why: tested[e.id].error ?? tested[e.id].outcome })}{brief(tested[e.id].responseExcerpt) ? ` — ${brief(tested[e.id].responseExcerpt)}` : ""}</p>{/if}{/each}{:else}<p class="text-sm text-mute">{t("No endpoints yet.")}</p>{/if}
    <div class="mt-3"><button class="btn primary" onclick={() => { resetHook(); sheet = "hook"; }} data-testid="new-hook">{t("Add endpoint")}</button></div>
    <Sheet open={sheet === "hook"} title={editing ? t("Change events") : t("New webhook endpoint")} onclose={() => (sheet = null)}>
      <form class="space-y-4" onsubmit={(e) => { e.preventDefault(); addHook(); }}><label class="label" for="hurl">{t("Your address (it must start with https://)")}</label><input id="hurl" data-autofocus class="field" type="url" placeholder="https://example.com/hooks/docustay" bind:value={url} disabled={!!editing} />
      <div><ChoiceMulti label={t("Tell me when a document is")} options={(topics.documents ?? []).filter((tp) => /\.(sent|opened|signed|executed|declined|voided|expired)$/.test(tp)).map((tp) => ({ value: tp, label: tp.replace("documents.document.", "") }))} bind:value={picked} mono testid="hook-events" /></div><div><ChoiceMulti label={t("Other events")} options={(topics.documents ?? []).filter((tp) => !/^documents\.document\.(sent|opened|signed|executed|declined|voided|expired)$/.test(tp) && !WORKBENCH_ONLY.has(tp)).map((tp) => ({ value: tp, label: tp.replace(/^documents\./, "") }))} bind:value={pickedMore} mono testid="hook-events-more" /></div><button class="btn primary" disabled={busy || !url.trim() || !(picked.length + pickedMore.length)}>{editing ? t("Save events") : t("Add endpoint")}</button></form>
    </Sheet></section>
  {/if}
  {/if}
</div>{/if}
